package test;
import org.eclipse.core.runtime.CoreException;
import org.eclipse.jdt.core.IJavaProject;
import org.eclipse.jdt.core.JavaCore;
import org.eclipse.core.resources.IProject;

// Mock classes for compilation purposes
interface IProject { boolean isOpen(); boolean hasNature(String id) throws CoreException; }
interface IJavaProject { Object getModuleDescription(); Object getOwnModuleDescription(); String getElementName(); }
class JavaCore { public static final String NATURE_ID = "jdt.core.nature"; public static IJavaProject create(IProject project) { return null; } }
class CoreException extends Exception { public CoreException(Object o, Object o2) {} }

public class ModulePatchSourceSelection {
    public void processProject(IProject project) throws CoreException {
        if (project.isOpen() && project.hasNature(JavaCore.NATURE_ID)) {
            IJavaProject jProj = JavaCore.create(project);
            if (jProj != null && jProj.getModuleDescription() == null) {
                System.out.println("Project " + jProj.getElementName() + " has no module description.");
            }
        }
    }
}

